package net.officefloor.hq.app.settings;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.regex.Pattern;
import net.officefloor.hq.app.rollup.Actor;
import net.officefloor.hq.app.sheet.InvalidSheetRequestException;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateSettings {
    /** An amount: 0.00 or more, with up to two decimals. */
    private static final Pattern AMOUNT = Pattern.compile("\\d{1,10}(\\.\\d{1,2})?");

    /** Terms: a whole number of days, 0 or more. */
    private static final Pattern DAYS = Pattern.compile("\\d{1,4}");

    /** The grades terms can be set for. */
    private static final Set<String> GRADES = Set.of("A", "B", "C");

    /** The settings that are dated, by key. */
    private static final Set<String> DATED = Set.of(Settings.CLERK_LIMIT, Settings.FLOOR, Settings.TERMS,
            Settings.gradeKey("A"), Settings.gradeKey("B"), Settings.gradeKey("C"),
            Settings.graceKey("A"), Settings.graceKey("B"), Settings.graceKey("C"), Settings.LATE_PCT, Settings.CAP,
            Settings.PROOF_THRESHOLD, Settings.proofKey("A"), Settings.proofKey("B"), Settings.proofKey("C"),
            Settings.NOTE_THRESHOLD);

    /** A month of the year: 1 to 12. */
    private static final Pattern MONTH = Pattern.compile("0?[1-9]|1[0-2]");

    /** A percent: 0.00 or more, with up to two decimals. */
    private static final Pattern PCT = Pattern.compile("\\d{1,5}(\\.\\d{1,2})?");

    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody SettingsRequest request,
            Settings settings, Sheets sheets, Out<SettingsChange> change, Out<Actor> actor) throws InvalidSheetRequestException {
        String limit = request == null || request.clerkLimit() == null ? null : request.clerkLimit().trim();
        if (limit != null && !limit.isEmpty() && !AMOUNT.matcher(limit).matches()) {
            throw new InvalidSheetRequestException("The clerk limit must be an amount with up to two decimals, or blank");
        }
        String floor = request == null || request.floor() == null ? null : request.floor().trim();
        if (floor != null && !floor.isEmpty() && !AMOUNT.matcher(floor).matches()) {
            throw new InvalidSheetRequestException("The floor must be an amount with up to two decimals, or blank");
        }
        String terms = request == null || request.terms() == null ? null : request.terms().trim();
        if (terms != null && !terms.isEmpty() && !DAYS.matcher(terms).matches()) {
            throw new InvalidSheetRequestException("The terms must be a whole number of days, or blank");
        }
        Map<String, Integer> gradeTerms = new TreeMap<>();
        if (request != null && request.gradeTerms() != null) {
            for (Map.Entry<String, String> e : request.gradeTerms().entrySet()) {
                if (!GRADES.contains(e.getKey())) {
                    throw new InvalidSheetRequestException("Terms can be set only for grade A, B or C");
                }
                String days = e.getValue() == null ? "" : e.getValue().trim();
                if (!days.isEmpty() && !DAYS.matcher(days).matches()) {
                    throw new InvalidSheetRequestException("The terms of a grade must be a whole number of days, or blank");
                }
                gradeTerms.put(e.getKey(), days.isEmpty() ? null : Integer.parseInt(days));
            }
        }
        Map<String, Integer> gradeGrace = new TreeMap<>();
        if (request != null && request.gradeGrace() != null) {
            for (Map.Entry<String, String> e : request.gradeGrace().entrySet()) {
                if (!GRADES.contains(e.getKey())) {
                    throw new InvalidSheetRequestException("Grace days can be set only for grade A, B or C");
                }
                String days = e.getValue() == null ? "" : e.getValue().trim();
                if (!days.isEmpty() && !DAYS.matcher(days).matches()) {
                    throw new InvalidSheetRequestException("The grace days of a grade must be a whole number of days, or blank");
                }
                gradeGrace.put(e.getKey(), days.isEmpty() ? null : Integer.parseInt(days));
            }
        }
        Map<String, BigDecimal> gradeProof = new TreeMap<>();
        if (request != null && request.gradeProof() != null) {
            for (Map.Entry<String, String> e : request.gradeProof().entrySet()) {
                if (!GRADES.contains(e.getKey())) {
                    throw new InvalidSheetRequestException("A proof threshold can be set only for grade A, B or C");
                }
                String amount = e.getValue() == null ? "" : e.getValue().trim();
                if (!amount.isEmpty() && !AMOUNT.matcher(amount).matches()) {
                    throw new InvalidSheetRequestException("The proof threshold of a grade must be an amount with up to two decimals, or blank");
                }
                gradeProof.put(e.getKey(), amount.isEmpty() ? null : new BigDecimal(amount).setScale(2));
            }
        }
        String late = request == null || request.latePct() == null ? null : request.latePct().trim();
        if (late != null && !late.isEmpty() && !PCT.matcher(late).matches()) {
            throw new InvalidSheetRequestException("The late percent must be a percent with up to two decimals, or blank");
        }
        String policy = request == null || request.policyDate() == null ? null : request.policyDate().trim();
        LocalDate policyDate = null;
        if (policy != null && !policy.isEmpty()) {
            try {
                policyDate = LocalDate.parse(policy);
            } catch (DateTimeParseException e) {
                throw new InvalidSheetRequestException("The policy date must be a date (yyyy-mm-dd), or blank");
            }
        }
        String numbering = request == null || request.periodNumberingFrom() == null ? null : request.periodNumberingFrom().trim();
        LocalDate numberingFrom = null;
        if (numbering != null && !numbering.isEmpty()) {
            try {
                numberingFrom = LocalDate.parse(numbering);
            } catch (DateTimeParseException e) {
                throw new InvalidSheetRequestException("The period numbering from must be a date (yyyy-mm-dd), or blank");
            }
        }
        String entry = request == null || request.entryDate() == null ? null : request.entryDate().trim();
        LocalDate entryDate = null;
        if (entry != null && !entry.isEmpty()) {
            try {
                entryDate = LocalDate.parse(entry);
            } catch (DateTimeParseException e) {
                throw new InvalidSheetRequestException("The entry date must be a date (yyyy-mm-dd), or blank");
            }
        }
        String cap = request == null || request.cap() == null ? null : request.cap().trim();
        if (cap != null && !cap.isEmpty() && !AMOUNT.matcher(cap).matches()) {
            throw new InvalidSheetRequestException("The cap must be an amount with up to two decimals, or blank");
        }
        String threshold = request == null || request.proofThreshold() == null ? null : request.proofThreshold().trim();
        if (threshold != null && !threshold.isEmpty() && !AMOUNT.matcher(threshold).matches()) {
            throw new InvalidSheetRequestException("The proof threshold must be an amount with up to two decimals, or blank");
        }
        String noteThreshold = request == null || request.noteThreshold() == null ? null : request.noteThreshold().trim();
        if (noteThreshold != null && !noteThreshold.isEmpty() && !AMOUNT.matcher(noteThreshold).matches()) {
            throw new InvalidSheetRequestException("The note threshold must be an amount with up to two decimals, or blank");
        }
        String pot = request == null || request.pot() == null ? null : request.pot().trim();
        if (pot != null && !pot.isEmpty() && !AMOUNT.matcher(pot).matches()) {
            throw new InvalidSheetRequestException("The pot must be an amount with up to two decimals, or blank");
        }
        String alert = request == null || request.alertThreshold() == null ? null : request.alertThreshold().trim();
        if (alert != null && !alert.isEmpty() && !AMOUNT.matcher(alert).matches()) {
            throw new InvalidSheetRequestException("The alert threshold must be an amount with up to two decimals, or blank");
        }
        String grace = request == null || request.graceDays() == null ? null : request.graceDays().trim();
        if (grace != null && !grace.isEmpty() && !DAYS.matcher(grace).matches()) {
            throw new InvalidSheetRequestException("The grace days must be a whole number of days, or blank");
        }
        String fiscal = request == null || request.fiscalStartMonth() == null ? null : request.fiscalStartMonth().trim();
        if (fiscal != null && !MONTH.matcher(fiscal).matches()) {
            throw new InvalidSheetRequestException("The fiscal year start month must be a month, 1 to 12");
        }
        String parent = request == null || request.parent() == null ? null : request.parent().trim();
        if (parent != null && !parent.isEmpty()) {
            if (parent.equals(sheetId)) {
                throw new InvalidSheetRequestException("A sheet cannot be its own parent");
            }
            if (!sheets.exists(parent)) {
                throw new InvalidSheetRequestException("The parent must be a sheet that has been loaded");
            }
            if (settings.isAncestor(sheetId, parent)) {
                throw new InvalidSheetRequestException("The parent cannot be a sheet that has this sheet as an ancestor");
            }
        }
        Map<String, String> perms = new LinkedHashMap<>();
        if (request != null && request.perms() != null) {
            for (Map.Entry<String, String> e : request.perms().entrySet()) {
                if (!Settings.PERM_ACTIONS.contains(e.getKey())) {
                    throw new InvalidSheetRequestException("Not an action of the permission matrix: " + e.getKey());
                }
                String value = e.getValue() == null ? "" : e.getValue().trim();
                List<String> roles = new ArrayList<>();
                if (!value.isEmpty()) {
                    for (String r : value.split(",", -1)) {
                        String role = r.trim().toLowerCase(Locale.ROOT);
                        if (!role.equals(Role.CLERK.show()) && !role.equals(Role.STEWARD.show())) {
                            throw new InvalidSheetRequestException("A permission is a comma separated list of roles (clerk, steward), or blank");
                        }
                        if (!roles.contains(role)) roles.add(role);
                    }
                }
                perms.put(e.getKey(), roles.isEmpty() ? null : String.join(",", roles));
            }
        }
        Map<String, LocalDate> froms = new TreeMap<>();
        if (request != null && request.from() != null) {
            for (Map.Entry<String, String> e : request.from().entrySet()) {
                if (!DATED.contains(e.getKey())) {
                    throw new InvalidSheetRequestException("Not a dated setting: " + e.getKey());
                }
                String from = e.getValue() == null ? "" : e.getValue().trim();
                if (from.isEmpty()) continue;
                try {
                    froms.put(e.getKey(), LocalDate.parse(from));
                } catch (DateTimeParseException ex) {
                    throw new InvalidSheetRequestException("A from-date must be a date (yyyy-mm-dd), or blank");
                }
            }
        }
        String by = request == null ? null : request.user();
        actor.set(new Actor(by));
        change.set(new SettingsChange(sheetId, limit != null,
                limit == null || limit.isEmpty() ? null : new BigDecimal(limit).setScale(2),
                floor == null ? null : floor.isEmpty() ? Settings.DEFAULT_FLOOR : new BigDecimal(floor).setScale(2),
                terms == null ? null : terms.isEmpty() ? Settings.DEFAULT_TERMS : Integer.parseInt(terms),
                late == null ? null : late.isEmpty() ? Settings.DEFAULT_LATE_PCT : new BigDecimal(late).setScale(2),
                policy != null, policyDate, numbering != null, numberingFrom, gradeTerms, by,
                cap != null, cap == null || cap.isEmpty() ? null : new BigDecimal(cap).setScale(2), froms,
                threshold != null, threshold == null || threshold.isEmpty() ? null : new BigDecimal(threshold).setScale(2), perms,
                grace != null, grace == null || grace.isEmpty() ? null : Integer.parseInt(grace),
                noteThreshold != null, noteThreshold == null || noteThreshold.isEmpty() ? null : new BigDecimal(noteThreshold).setScale(2),
                entry != null, entryDate, gradeGrace, gradeProof,
                pot != null, pot == null || pot.isEmpty() ? null : new BigDecimal(pot).setScale(2),
                parent != null, parent == null || parent.isEmpty() ? null : parent,
                fiscal == null ? null : Integer.parseInt(fiscal),
                alert != null, alert == null || alert.isEmpty() ? null : new BigDecimal(alert).setScale(2)));
    }
}
package net.officefloor.hq.app.settings;

import java.math.BigDecimal;
import java.time.LocalDate;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;

/** A dated setting is recorded from its from-date, else from the sheet's today. */
public class SaveSettings {
    public void save(@Val SettingsChange change, Settings settings, Sheets sheets) {
        String sheetId = change.sheetId();
        LocalDate today = sheets.today(sheetId);
        if (change.setsClerkLimit()) setDated(settings, change, today, Settings.CLERK_LIMIT, change.clerkLimit());
        if (change.floor() != null) setDated(settings, change, today, Settings.FLOOR, change.floor());
        if (change.terms() != null) setDated(settings, change, today, Settings.TERMS, BigDecimal.valueOf(change.terms()));
        change.gradeTerms().forEach((grade, terms) -> setDated(settings, change, today, Settings.gradeKey(grade),
                terms != null ? BigDecimal.valueOf(terms) : null));
        change.gradeGrace().forEach((grade, days) -> setDated(settings, change, today, Settings.graceKey(grade),
                days != null ? BigDecimal.valueOf(days) : null));
        if (change.latePct() != null) setDated(settings, change, today, Settings.LATE_PCT, change.latePct());
        if (change.setsPolicyDate()) settings.setPolicyDate(sheetId, change.policyDate());
        if (change.setsCap()) setDated(settings, change, today, Settings.CAP, change.cap());
        if (change.setsProofThreshold()) setDated(settings, change, today, Settings.PROOF_THRESHOLD, change.proofThreshold());
        change.gradeProof().forEach((grade, threshold) -> setDated(settings, change, today, Settings.proofKey(grade), threshold));
        if (change.setsNoteThreshold()) setDated(settings, change, today, Settings.NOTE_THRESHOLD, change.noteThreshold());
        if (change.setsPeriodNumberingFrom()) settings.setPeriodNumberingFrom(sheetId, change.periodNumberingFrom());
        if (change.setsEntryDate()) settings.setEntryDate(sheetId, change.entryDate());
        if (change.setsPot()) settings.setPot(sheetId, change.pot());
        if (change.setsParent()) settings.setParent(sheetId, change.parent());
        if (change.setsGraceDays()) settings.setGraceDays(sheetId, change.graceDays());
        if (change.fiscalStartMonth() != null) settings.setFiscalStartMonth(sheetId, change.fiscalStartMonth());
        if (change.setsAlertThreshold()) settings.setAlertThreshold(sheetId, change.alertThreshold());
        change.perms().forEach((action, roles) -> settings.setPermission(sheetId, action, roles));
    }

    private static void setDated(Settings settings, SettingsChange change, LocalDate today, String key, BigDecimal value) {
        settings.setDated(change.sheetId(), key, change.froms().getOrDefault(key, today), value);
    }
}
package net.officefloor.hq.app.settings;

import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;

/** Runs after the settings are saved, so a refused change writes no audit line. A line per setting
 *  set, a dated one ending in its from-date when one was given. */
public class RecordSettingChanged {
    public void record(@Val SettingsChange change, Audit audit) {
        String prefix = "SETTING_CHANGED sheet=" + change.sheetId() + " by=" + change.by();
        if (change.setsClerkLimit()) {
            audit.record(prefix + " key=clerk-limit value="
                    + (change.clerkLimit() != null ? change.clerkLimit().toPlainString() : "")
                    + from(change, Settings.CLERK_LIMIT));
        }
        if (change.floor() != null) {
            audit.record(prefix + " key=floor value=" + change.floor().toPlainString() + from(change, Settings.FLOOR));
        }
        if (change.terms() != null) {
            audit.record(prefix + " key=terms value=" + change.terms() + from(change, Settings.TERMS));
        }
        change.gradeTerms().forEach((grade, terms) ->
                audit.record(prefix + " key=terms-" + grade + " value=" + (terms != null ? terms : "")
                        + from(change, Settings.gradeKey(grade))));
        change.gradeGrace().forEach((grade, days) ->
                audit.record(prefix + " key=" + Settings.graceKey(grade) + " value=" + (days != null ? days : "")
                        + from(change, Settings.graceKey(grade))));
        if (change.latePct() != null) {
            audit.record(prefix + " key=late-pct value=" + change.latePct().toPlainString() + from(change, Settings.LATE_PCT));
        }
        if (change.setsPolicyDate()) {
            audit.record(prefix + " key=policy-date value="
                    + (change.policyDate() != null ? change.policyDate().toString() : ""));
        }
        if (change.setsPeriodNumberingFrom()) {
            audit.record(prefix + " key=period-numbering-from value="
                    + (change.periodNumberingFrom() != null ? change.periodNumberingFrom().toString() : ""));
        }
        if (change.setsCap()) {
            audit.record(prefix + " key=cap value=" + (change.cap() != null ? change.cap().toPlainString() : "")
                    + from(change, Settings.CAP));
        }
        if (change.setsProofThreshold()) {
            audit.record(prefix + " key=proof-threshold value="
                    + (change.proofThreshold() != null ? change.proofThreshold().toPlainString() : "")
                    + from(change, Settings.PROOF_THRESHOLD));
        }
        change.gradeProof().forEach((grade, threshold) ->
                audit.record(prefix + " key=" + Settings.proofKey(grade) + " value="
                        + (threshold != null ? threshold.toPlainString() : "") + from(change, Settings.proofKey(grade))));
        if (change.setsNoteThreshold()) {
            audit.record(prefix + " key=note-threshold value="
                    + (change.noteThreshold() != null ? change.noteThreshold().toPlainString() : "")
                    + from(change, Settings.NOTE_THRESHOLD));
        }
        change.perms().forEach((action, roles) ->
                audit.record(prefix + " key=" + Settings.permKey(action) + " value=" + (roles != null ? roles : "")));
        if (change.setsGraceDays()) {
            audit.record(prefix + " key=grace-days value=" + (change.graceDays() != null ? change.graceDays() : ""));
        }
        if (change.setsEntryDate()) {
            audit.record(prefix + " key=entry-date value="
                    + (change.entryDate() != null ? change.entryDate().toString() : ""));
        }
        if (change.setsPot()) {
            audit.record(prefix + " key=pot value=" + (change.pot() != null ? change.pot().toPlainString() : ""));
        }
        if (change.setsParent()) {
            audit.record(prefix + " key=parent value=" + (change.parent() != null ? change.parent() : ""));
        }
        if (change.fiscalStartMonth() != null) {
            audit.record(prefix + " key=fiscal-start-month value=" + change.fiscalStartMonth());
        }
        if (change.setsAlertThreshold()) {
            audit.record(prefix + " key=alert-threshold value="
                    + (change.alertThreshold() != null ? change.alertThreshold().toPlainString() : ""));
        }
    }

    /** " from=<date>" when a from-date was given for the key, else nothing. */
    private static String from(SettingsChange change, String key) {
        LocalDate from = change.froms().get(key);
        return from != null ? " from=" + from : "";
    }
}
package net.officefloor.hq.app.settings;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;

/** The sheet's settings as the screen sees them, each dated one as in force on the sheet's today:
 *  the clerk limit with two decimals (null for no limit), the floor with two decimals, the terms in days, the late percent with two decimals, the policy date as set (yyyy-mm-dd, null when blank), the period numbering from (yyyy-mm-dd, null when off), the terms set per grade, by grade (a grade not in it uses the sheet's terms), the cap with two decimals (null for no cap), and the roles given, by user name;
 *  and every value recorded for the dated settings, by key, oldest from-date first; and the proof threshold
 *  with two decimals (null for none); and the permissions set, by action (roles comma separated; an action not in it keeps the standing rule); and the grace days (null when off); and every delegation of the steward role, oldest first; and the note threshold with two decimals (null for none); and the entry date (yyyy-mm-dd, null when off); and the grace days set per grade, by grade (a grade not in it has none); and the proof threshold set per grade with two decimals, by grade (a grade not in it uses the sheet's); and the pot with two decimals (null for none); and the parent sheet id (null for none); and the fiscal year start month (1 to 12); and the alert threshold with two decimals (null for off). */
public record SettingsResponse(String clerkLimit, String floor, int terms, String latePct, String policyDate, String periodNumberingFrom, Map<String, Integer> gradeTerms, String cap, List<RoleResponse> roles,
        Map<String, List<Settings.DatedValue>> dated, String proofThreshold, Map<String, String> perms, Integer graceDays,
        List<DelegationResponse> delegations, String noteThreshold, String entryDate, Map<String, Integer> gradeGrace, Map<String, String> gradeProof, String pot, String parent, int fiscalStartMonth, String alertThreshold) {
    public static SettingsResponse of(String sheetId, LocalDate today, Settings settings) {
        BigDecimal limit = settings.clerkLimit(sheetId);
        LocalDate policyDate = settings.policyDate(sheetId);
        BigDecimal cap = settings.cap(sheetId);
        BigDecimal threshold = settings.proofThreshold(sheetId, today);
        BigDecimal noteThreshold = settings.noteThreshold(sheetId, today);
        LocalDate numberingFrom = settings.periodNumberingFrom(sheetId);
        LocalDate entryDate = settings.entryDate(sheetId);
        BigDecimal pot = settings.pot(sheetId);
        BigDecimal alert = settings.alertThreshold(sheetId);
        return new SettingsResponse(limit != null ? limit.toPlainString() : null,
                settings.floor(sheetId, today).toPlainString(), settings.terms(sheetId, today),
